// Class 10 Social Science practice bank, part 5: Political Science (Power Sharing, Federalism, Gender Religion and Caste, Political Parties, Outcomes of Democracy). Extra board-style questions for year-long practice (unreviewed draft).
(function () {
  const AR_OPTS = ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."];
  let n = 1;
  // M(level, question, right answer, three wrong answers, explanation): the right answer is stored at a varying position.
  function M(level, q, right, wrong, explain) {
    const at = (n++) % 4;
    const options = wrong.slice();
    options.splice(at, 0, right);
    return { q, options, answer: at, explain, level };
  }
  // AR(level, assertion, reason, answer index, explanation): assertion-reason with fixed options.
  function AR(level, a, r, answer, explain) {
    return { q: "Assertion (A): " + a + "\nReason (R): " + r, options: AR_OPTS, answer, explain, level, keepOrder: true };
  }
  // W(marks, question, model answer, type?)
  function W(marks, q, a, type) {
    const o = { q, a, marks };
    if (type) o.type = type;
    return o;
  }
  StudyData.addPractice(10, "sst", {
  "power-sharing": {
    mcq: [
      M(1, "What share of Belgium's population lives in the Flemish region and speaks Dutch?", "59 per cent", ["40 per cent", "1 per cent", "80 per cent"], "About 59 per cent are Dutch speakers, 40 per cent French speakers and 1 per cent German speakers."),
      M(1, "The people of Wallonia in Belgium mostly speak", "French", ["Dutch", "German", "English"], "About 40 per cent of Belgians live in Wallonia and speak French."),
      M(1, "In the capital city Brussels, the share of French speakers is", "80 per cent", ["59 per cent", "40 per cent", "20 per cent"], "In Brussels 80 per cent speak French and 20 per cent speak Dutch."),
      M(1, "The Belgian Constitution was amended four times between", "1970 and 1993", ["1950 and 1960", "1948 and 1956", "1980 and 2009"], "The amendments were to recognise regional differences and cultural diversity."),
      M(1, "Which separate country did militant Tamil groups demand in Sri Lanka in the 1980s?", "Tamil Eelam", ["Tamil Nadu", "Dravida Nadu", "Ceylon"], "Groups demanded Tamil Eelam in the north and east."),
      M(1, "The civil war in Sri Lanka came to an end in", "2009", ["1948", "1956", "1993"], "Sri Lanka became independent in 1948 and the Sinhala-only Act was passed in 1956."),
      M(1, "Which reason for power sharing stresses the intrinsic value of power sharing as the spirit of democracy?", "Moral reason", ["Prudential reason", "Economic reason", "Military reason"], "Moral reasons stress the value of power sharing itself, while prudential reasons stress better outcomes."),
      M(1, "Sri Lanka is an island nation lying off the southern coast of", "Tamil Nadu", ["Kerala", "Andhra Pradesh", "Odisha"], "Sri Lanka lies just off the southern coast of Tamil Nadu."),
      M(2, "Indian Tamils in Sri Lanka are mainly", "descendants of plantation workers", ["recent migrants from Kerala and Karnataka", "traders from the Gujarat coast", "soldiers of an ancient Chola army"], "Sri Lankan Tamils (13 per cent) are the descendants of earlier Tamil settlers."),
      M(2, "In Belgium the 'community government' is elected by", "people of one language community", ["all the citizens of Brussels", "the central ministers only", "the European Union"], "It looks after cultural, educational and language-related issues."),
      M(2, "Which step did the Sri Lankan government NOT take to establish Sinhala supremacy?", "Giving regional autonomy to the Tamil areas", ["Making Sinhala the only official language", "Preferential treatment of Sinhala applicants for jobs", "Protecting and fostering Buddhism"], "The Tamils' demand for regional autonomy was not accepted."),
      M(2, "Reserved constituencies for weaker sections and women in India are an example of power sharing among", "social groups", ["organs of government", "levels of government", "political parties"], "Such reservation gives social groups a share in power."),
      M(2, "Pressure groups and movements share power when they", "influence government decisions", ["form the government", "appoint judges", "write the Constitution"], "Traders, farmers, workers and others influence the government."),
      M(2, "In Belgium's central government the number of Dutch-speaking and French-speaking ministers is", "equal", ["three times as many Dutch speakers", "chosen by the European Union", "always in favour of the French"], "Equal numbers prevent any one community from dominating the Centre."),
      M(2, "Prudential reasons for power sharing stress", "better outcomes such as stability", ["only the spirit of democracy", "the rule of one group", "the abolition of elections"], "Power sharing reduces conflict between social groups and ensures political stability."),
      M(2, "In Brussels, the government is a", "a separate government with equal representation", ["a government run only by Dutch speakers", "a government run only by German speakers", "a branch of the king's own court"], "This is part of the Belgian model."),
      M(2, "Alongside the demand for recognition of Tamil and regional autonomy, the Sri Lankan Tamils also demanded", "equal opportunity in jobs", ["a Tamil-speaking head of state", "a separate Tamil currency note", "a complete ban on Buddhism"], "Their demands were not accepted, which led to deep alienation."),
      M(3, "Match: (1) horizontal distribution, (2) vertical distribution, (3) among social groups, (4) among political parties. With: (P) coalition government, (Q) Union, state and local governments, (R) legislature, executive and judiciary, (S) community government in Belgium.", "1-R, 2-Q, 3-S, 4-P", ["1-Q, 2-R, 3-S, 4-P", "1-R, 2-Q, 3-P, 4-S", "1-S, 2-Q, 3-R, 4-P"], "Horizontal sharing is among organs; vertical is among levels."),
      M(3, "Brussels has 20 lakh people, 80 per cent of whom speak French. The number of Dutch speakers is", "4 lakh", ["16 lakh", "8 lakh", "20 lakh"], "The remaining 20 per cent of 20 lakh is 4 lakh."),
      M(3, "A result of the majoritarian measures of the Sri Lankan government was", "Tamils' alienation and civil war", ["Tamils abandoning all demands", "the creation of a federation", "the union of Sri Lanka with India"], "The Tamils felt that the constitution and government policies denied them equal political rights."),
      AR(2, "Power sharing is the very spirit of democracy.", "People have a right to be consulted on how they are governed.", 0, "This is the moral reason for power sharing."),
      AR(2, "Belgium succeeded in avoiding a division of the country.", "Its leaders respected the feelings and interests of different communities.", 0, "Accommodating all communities prevented conflict."),
      AR(3, "In Belgium the French-speaking community was the majority of the population.", "The French-speaking minority was relatively rich and powerful.", 3, "French speakers were about 40 per cent, a minority, so A is false."),
      AR(2, "Horizontal power sharing is also called a system of checks and balances.", "Each organ of government checks the others, so no organ can exercise unlimited power.", 0, "The organs balance each other."),
      AR(3, "Brussels was chosen as the headquarters of the European Union.", "The Belgian model of power sharing succeeded in avoiding conflict.", 1, "Both are true, but the choice was not caused by the success of the model."),
    ],
    written: [
      W(2, "What is the community government in Belgium?", "A third kind of government elected by people of one language community (Dutch, French or German), irrespective of where they live.\nIt has the power over cultural, educational and language-related issues."),
      W(2, "State the demands of the Sri Lankan Tamils.", "Recognition of Tamil as an official language, regional autonomy and equality of opportunity in jobs and education.\nBy the 1980s several political organisations demanded an independent Tamil Eelam in the north and east."),
      W(2, "Give one example of power sharing among social groups in India.", "Reserved constituencies in the legislatures for weaker sections such as the Scheduled Castes and Scheduled Tribes.\nReservation of seats for women in local bodies."),
      W(2, "How does a coalition government illustrate power sharing?", "A coalition government is formed by two or more political parties.\nThe parties share power by sharing ministries and policy decisions."),
      W(3, "Distinguish between horizontal and vertical distribution of power with one example each.", "Horizontal: power is shared among organs of government at the same level, such as the legislature, executive and judiciary.\nVertical: power is shared among governments at different levels, such as the Union, state and local governments.\nExamples: the judiciary checking the executive (horizontal); the Union and state governments each having their own powers (vertical)."),
      W(3, "Why did Belgium's leaders change the Constitution four times between 1970 and 1993?", "The French-speaking minority was richer and more powerful, while the Dutch-speaking majority got the benefits of development and education later, causing tension.\nThey recognised the existence of regional differences and cultural diversities.\nThey therefore changed the Constitution to build a model which could accommodate all communities and avoid civil strife."),
      W(3, "How do pressure groups and movements share power in a democracy? Give three points.", "Interest groups of traders, businessmen, industrialists, farmers and industrial workers put pressure on the government.\nThey influence decision-making in the political process.\nMovements such as those of workers or farmers also take part in discussions and policies, sharing power informally."),
      W(3, "Compare the Sinhala and Tamil communities of Sri Lanka in population and religion.", "Sinhala speakers are about 74 per cent of the population and Tamil speakers about 18 per cent (Sri Lankan Tamils 13 per cent and Indian Tamils).\nMost Sinhala speakers are Buddhist.\nMost Tamils are Hindus or Muslims, and about 7 per cent of the people are Christians."),
      W(5, "How does power sharing help to build a stable and legitimate democracy? Discuss the prudential and moral reasons using Belgium and Sri Lanka.", "Prudential reasons: power sharing reduces the possibility of conflict between social groups and so ensures political stability.\nImposing the will of the majority may look attractive but it is oppressive for the minority and ruinous for the majority in the long run.\nBelgium shared power among language communities and avoided civil strife; Sri Lanka's majoritarianism led to civil war that ended in 2009.\nMoral reasons: power sharing is the very spirit of democracy; people have a right to be consulted on how they are governed.\nA legitimate government is one in which citizens have a stake, and power sharing gives them that stake."),
      W(4, "Case study: In country Z, 65 per cent of the people speak language A and 35 per cent speak language B. The government declares language A as the only official language and gives it the major share of government jobs. People of group B feel excluded and begin to demand a separate state.\n(i) Name the Sri Lankan Act of 1956 which resembles this policy. (1)\n(ii) What is such a policy called? (1)\n(iii) Suggest two steps to avoid conflict. (2)", "(i) The Act of 1956 that made Sinhala the only official language. (1)\n(ii) Majoritarianism. (1)\n(iii) Any two: share power with the minority; recognise both languages; give regional autonomy; reserve a share of jobs and offices for all groups. (2)", "case"),
    ]
  },
  "federalism": {
    mcq: [
      M(1, "In a unitary system the sub-units are", "subordinate to the central government", ["equal to the central government", "independent of the central government", "elected by the central government"], "Under a unitary system there is either one level of government or the sub-units are subordinate to the centre."),
      M(1, "Which of these countries is a 'coming together' federation?", "USA", ["India", "Spain", "Belgium"], "India, Spain and Belgium are 'holding together' federations."),
      M(1, "Banking and currency belong to the", "Union List", ["State List", "Concurrent List", "Residuary list"], "The Union List has subjects of national importance."),
      M(1, "Irrigation is a subject in the", "State List", ["Union List", "Concurrent List", "Residuary list"], "The State List has police, trade, commerce, agriculture and irrigation."),
      M(1, "Marriage and adoption are subjects of the", "Concurrent List", ["Union List", "State List", "Residuary list"], "Both the Union and the states can make laws on them."),
      M(1, "Which of these is a Union Territory?", "Chandigarh", ["Nagaland", "Uttarakhand", "Jharkhand"], "Union Territories like Chandigarh and Lakshadweep are too small to be states."),
      M(1, "Besides Hindi, how many other languages are recognised as Scheduled Languages?", "21", ["18", "10", "25"], "India has no national language; Hindi is the official language."),
      M(1, "The head of a municipal corporation in a big city is the", "mayor", ["sarpanch", "chairperson of the zilla parishad", "municipal chairperson"], "In municipalities, the head is the municipal chairperson."),
      M(2, "Which of these is NOT a feature of federalism?", "Provisions can be changed by the Centre alone", ["Two or more levels of government", "Courts act as umpire", "Jurisdictions are specified in the Constitution"], "In a federation fundamental provisions cannot be changed by one level alone."),
      M(2, "In 'holding together' federations the central government tends to be", "more powerful", ["less powerful", "equal to the units in power", "absent"], "Units may also have unequal powers."),
      M(2, "Which of these states was created on the basis of culture, ethnicity or geography rather than language?", "Uttarakhand", ["Karnataka", "Andhra Pradesh", "Tamil Nadu"], "Nagaland, Uttarakhand and Jharkhand were created on non-linguistic grounds."),
      M(2, "The movement against the end of English as an official language in 1965 turned violent in", "Tamil Nadu", ["Punjab", "Kerala", "Assam"], "The Centre agreed to continue English along with Hindi."),
      M(2, "After 1990, the rise of regional parties and coalition governments led to", "more respect for the autonomy of states", ["the end of coalitions", "the centralisation of power", "the stoppage of state elections"], "The Centre had to share power with regional parties."),
      M(2, "Local government is called the third tier of government because it", "is a level below the states", ["has more power than the states", "replaces the Centre", "is run by the Supreme Court"], "Federalism is extended by decentralisation to the local level."),
      M(2, "Elections to the panchayats and municipalities are conducted by the", "State Election Commission", ["Election Commission of India", "Zila Parishad", "Gram Sabha"], "It is an independent body."),
      M(2, "The gram sabha consists of", "all the voters of the village", ["only the panches", "only the sarpanch", "only landowners"], "The gram panchayat works under the gram sabha."),
      M(2, "A panchayat samiti is formed by", "a group of gram panchayats", ["all the zilla parishads", "the municipalities of a state", "the women of a village"], "All the panchayat samitis in a district form the zilla parishad."),
      M(3, "Match: (1) police, (2) education, (3) foreign affairs, (4) computer software. With: (P) Concurrent List, (Q) State List, (R) Union List, (S) residuary subject with the Union government.", "1-Q, 2-P, 3-R, 4-S", ["1-P, 2-Q, 3-R, 4-S", "1-Q, 2-R, 3-P, 4-S", "1-Q, 2-P, 3-S, 4-R"], "Police is a state subject, education concurrent and foreign affairs Union; software is residuary."),
      M(3, "Arrange the rural local bodies from the village to the district level: (a) zilla parishad, (b) gram panchayat, (c) panchayat samiti.", "(b), (c), (a)", ["(a), (c), (b)", "(c), (b), (a)", "(b), (a), (c)"], "Gram panchayats form a samiti and all samitis form a zilla parishad."),
      M(3, "If a law on trade unions passed by Parliament conflicts with a state law, which one prevails?", "The Union law", ["The state law", "Neither of them", "Whichever was passed later"], "Trade unions are on the Concurrent List, where Union law prevails."),
      AR(2, "India is a 'holding together' type of federation.", "A large country divides its power between the constituent states and the national government.", 0, "India was already a large unit that shared power among states."),
      AR(3, "In India the Centre is more powerful than the states.", "Residuary subjects belong to the Union and Union law prevails in the Concurrent List.", 0, "These two provisions favour the Union."),
      AR(2, "Reservation of one-third of seats for women in local bodies increased their role in local politics.", "The 1992 amendment made regular elections to local bodies mandatory.", 1, "Both are true, but regular elections do not explain the increased role of women."),
      AR(3, "State governments have given full powers and resources to local governments.", "The 1992 amendment made it mandatory for states to share some powers and revenue with local governments.", 3, "Most states have not transferred significant powers, so A is false."),
      AR(3, "The use of English for official purposes ended in 1965.", "Non-Hindi-speaking states demanded that English should continue and the Centre agreed.", 3, "English was continued, so A is false."),
    ],
    written: [
      W(2, "What is the language policy of India?", "India has no national language; Hindi is the official language.\nBesides Hindi, 21 other languages are recognised as Scheduled Languages, and English continues along with Hindi for official use."),
      W(2, "How is a Union Territory different from a state?", "Union Territories like Chandigarh, Lakshadweep and Delhi are too small to be states.\nThe Central government has special powers in running these areas."),
      W(2, "State two advantages of decentralisation.", "Local people know the local problems best and can decide better.\nIt promotes direct participation of people in democracy and makes administration easier."),
      W(2, "Who has the power to legislate on residuary subjects in India? Give an example.", "The Union government has the power on subjects that are not in any of the three lists.\nExample: computer software."),
      W(3, "How did the reorganisation of states help India? Give three points.", "Many old states were reorganised on the basis of language, so people of one language lived in one state.\nIt made the country more united and administration easier.\nSome states, such as Nagaland, Uttarakhand and Jharkhand, were created on the basis of culture, ethnicity or geography."),
      W(3, "How did Centre-state relations change after 1990?", "Earlier the Centre sometimes misused the Constitution to dismiss state governments run by rival parties.\nAfter 1990 regional parties rose in many states and coalition governments came at the Centre.\nThis led to a new culture of power sharing and respect for the autonomy of state governments."),
      W(3, "What is the role of the gram sabha? Why is it important?", "The gram sabha consists of all the voters of a village and the gram panchayat works under it.\nIt is the decision-making body at the village level and keeps the panchayat accountable.\nIts importance is lost when it is not held regularly."),
      W(3, "How are disputes between Union and state laws on the Concurrent List resolved? Give two examples of subjects on this list.", "The Concurrent List includes subjects of common interest such as education, forest, trade unions, marriage, adoption and succession.\nBoth the Union and the state governments can make laws on them.\nIf their laws conflict, the law made by the Union government prevails."),
      W(5, "Explain the two routes through which federations are formed. Under which route does India fall? Why?", "In the 'coming together' route, independent states come together to form a bigger unit; the states usually have equal powers. Examples: USA, Switzerland and Australia.\nIn the 'holding together' route, a large country decides to divide its power between the constituent states and the national government; the central government tends to be more powerful and states may have unequal powers. Examples: India, Spain and Belgium.\nIndia falls under 'holding together', because the Constitution declared India a Union of States and divided power between the Centre and states, with the Union more powerful.\nThe Union List, State List and Concurrent List specify jurisdictions.\nThe Union has the residuary subjects."),
      W(4, "Case study: In 1965, when the use of English for official purposes was due to stop, people in some non-Hindi-speaking states opposed this. In Tamil Nadu the movement turned violent. The Central government then decided that English would continue along with Hindi.\n(i) What was the effect of the decision on the language policy? (1)\n(ii) Why did non-Hindi-speaking states oppose the change? (1)\n(iii) What does this show about federalism in India? (2)", "(i) English continued to be used along with Hindi for official purposes. (1)\n(ii) They feared that Hindi would be imposed on them and they would lose out. (1)\n(iii) Any two: the Centre respected the wishes of the states; power was shared between the Centre and states; federalism accommodates regional diversity. (2)", "case"),
    ]
  },
  "gender-religion-and-caste": {
    mcq: [
      M(1, "In which of these countries is women's participation in public life very high?", "Sweden", ["India", "Bangladesh", "Pakistan"], "The Scandinavian countries (Sweden, Norway, Finland) have a high participation of women in public life."),
      M(1, "The law to reserve one-third of seats for women in the Lok Sabha and the state assemblies was passed in", "2023", ["1992", "2009", "1950"], "It is to take effect after the next delimitation."),
      M(1, "A society in which men dominate women is called a", "patriarchal society", ["secular society", "communal society", "feudal society"], "India is still a male-dominated, patriarchal society."),
      M(1, "Who said that religion can never be separated from politics?", "Gandhiji", ["B.R. Ambedkar", "Periyar Ramaswami Naicker", "Jotiba Phule"], "Gandhiji meant moral values common to all religions."),
      M(1, "Women organised agitations in different countries for equal rights, such as the right to vote and", "educational opportunities", ["lower taxes for all households", "longer working hours at home", "separate schools for girls only"], "Radical feminist movements also demanded equality in personal and family life."),
      M(1, "Which social reformer of Madras worked for a society without caste inequalities?", "Periyar Ramaswami Naicker", ["Jotiba Phule", "B.R. Ambedkar", "Mahatma Gandhi"], "Phule, Ambedkar and Gandhiji also worked against caste."),
      M(1, "By banning untouchability the Indian state", "intervenes to ensure equality", ["supports one religion", "stops all religious practice", "fixes the number of festivals"], "This is one example of the state intervening in religious matters."),
      M(1, "Housework being seen as a woman's duty is an example of a", "social stereotype", ["law of the state", "biological fact", "religious ritual"], "Gender division is based on social expectations and stereotypes, not on biology."),
      M(2, "Which of these is an example of communal political mobilisation?", "Using religious symbols to win votes", ["Selling goods to people of every faith", "Celebrating a festival at home", "Visiting a temple with friends"], "Communal mobilisation uses religion as the basis of politics."),
      M(2, "Most victims of communal riots are", "religious minorities", ["the majority community", "politicians", "government officers"], "Human rights groups point this out."),
      M(2, "Who argues that family laws of all religions discriminate against women?", "The women's movement", ["The Election Commission", "Landlords", "Courts"], "The women's movement demands equal rights in the family."),
      M(2, "Which of these is NOT a reason for the weakening of caste barriers?", "Growing power of landlords in villages", ["Urbanisation", "Growth of literacy and education", "Occupational mobility"], "The weakening of landlords in villages has helped."),
      M(2, "In India no parliamentary constituency has", "a clear majority of one single caste", ["a single party winning always", "fewer than five caste groups", "only urban voters"], "So a candidate cannot win with the votes of one caste alone."),
      M(2, "Caste groups try to expand their power by", "including neighbouring sub-castes", ["breaking all alliances", "avoiding elections", "banning inter-caste marriage"], "They also form coalitions with other castes or communities."),
      M(2, "Excessive focus on caste in politics can", "side-line issues like poverty", ["reduce corruption", "end poverty", "increase literacy"], "It may also lead to tensions and violence."),
      M(2, "The belief in the superiority of one's own religion is which form of communalism?", "Everyday beliefs", ["Communal violence", "Political mobilisation", "A separate political unit"], "It is the most common form, built on prejudices and stereotypes."),
      M(2, "Radical feminist movements demanded equality in", "personal and family life", ["only the military", "only sports", "only foreign trade"], "Other movements demanded the right to vote and better legal status."),
      M(3, "Match: (1) Sri Lanka, (2) Pakistan, (3) England, (4) India. With the status of religion: (P) Islam official, (Q) Christianity official, (R) no official religion, (S) Buddhism has a special status.", "1-S, 2-P, 3-Q, 4-R", ["1-P, 2-S, 3-Q, 4-R", "1-S, 2-Q, 3-P, 4-R", "1-R, 2-P, 3-Q, 4-S"], "India has no official religion."),
      M(3, "If a legislature has 600 seats and one-third are reserved for women, the number of reserved seats is", "200", ["180", "100", "300"], "600 divided by 3 is 200."),
      M(3, "Which fact shows that caste alone does not decide election results?", "Ruling parties and sitting MPs and MLAs often lose elections", ["Every constituency has a clear majority of one caste", "A party gets all the votes of a caste", "Candidates are always of different castes"], "If caste alone decided, sitting members would not often lose."),
      AR(2, "India is a secular state.", "It has no official religion and gives all individuals the freedom to practise any religion.", 0, "A state with no official religion and freedom for all is secular."),
      AR(2, "Local bodies have given women a voice in politics.", "One-third of the seats in panchayats and municipalities are reserved for women.", 0, "Reservation brings women into the decision-making."),
      AR(3, "Caste has completely disappeared from Indian life.", "Most people still marry within their caste and untouchability persists.", 3, "Caste is still important in life, so A is false."),
      AR(3, "Gandhiji said that religion can never be separated from politics.", "By religion he meant moral values common to all religions.", 0, "He did not mean communal politics but ethics."),
      AR(2, "Communalism arises when religion is seen as the basis of the nation.", "One religion is projected as superior and state power is used to establish the dominance of one group.", 0, "This is how communal politics works."),
    ],
    written: [
      W(2, "What does the Equal Wages Act provide? Is it fully followed?", "It provides for equal wages for equal work.\nIn practice, in many fields women are paid less than men for the same work."),
      W(2, "What is meant by a secular state? Give one feature.", "A state with no official religion, which treats all religions equally.\nThe Constitution gives freedom to profess, practise and propagate any religion, or not to follow any."),
      W(2, "What is communal politics?", "Politics based on the idea that religion is the principal basis of social community.\nIt projects one religion as superior and uses it to seek political power."),
      W(2, "How have urbanisation and education affected caste in India?", "They have weakened caste barriers, because people from different castes live and work together in cities.\nLiteracy and occupational mobility reduce the importance of hereditary occupations."),
      W(3, "Explain three reasons why women's representation in India's legislatures is low.", "India is a male-dominated society where women's role is mostly restricted to the home.\nLiteracy among women is lower and they get less support for higher studies and careers.\nParties give few tickets to women, and the law for reservation in Lok Sabha and state assemblies is yet to take effect."),
      W(3, "How do caste groups enter politics? Give three points.", "Parties choose candidates keeping the caste composition of the electorate in mind.\nParties appeal to caste sentiment to gain support.\nCaste groups try to expand by including neighbouring sub-castes and forming coalitions with other castes or communities."),
      W(3, "State three consequences of giving too much importance to caste in politics.", "It diverts attention from other pressing issues such as poverty, development and corruption.\nIt can lead to tensions and sometimes violence.\nIt creates new divisions such as 'backward' and 'forward' groups."),
      W(3, "What is the sexual division of labour? How does it affect women?", "Most work inside the home is done by women or organised by them, while men do the work outside the home.\nWomen's work at home is not paid or valued.\nAs a result women face disadvantage in education, jobs and politics."),
      W(5, "Explain the positive and negative aspects of the relationship between caste and politics in India.", "Positive: universal adult franchise forced leaders to seek the votes of every caste and created new consciousness among castes treated as inferior.\nIt strengthened the claims of the disadvantaged for equal status.\nNegative: too much stress on caste can divert attention from poverty, development and corruption and may lead to tension and violence.\nLimits of caste in politics: no constituency has a clear majority of one caste, no party gets all the votes of a caste, many candidates come from the same caste, and ruling parties and sitting members often lose.\nPolitics also influences caste, as groups try to expand and new groupings like 'backward' and 'forward' emerge."),
      W(4, "Case study: Before an election a party leader decides to give tickets only to candidates from the dominant caste in each constituency. He appeals to the voters on caste lines. After the election, his party loses in several constituencies.\n(i) Name the feature of caste in politics seen here. (1)\n(ii) Why did the party lose in spite of this strategy? (2)\n(iii) State one harm of caste-based politics. (1)", "(i) Parties choose candidates and appeal for votes on the basis of caste. (1)\n(ii) Any two: no constituency has a clear majority of one single caste; no party gets all the votes of a caste; voters also look at the party's performance, the candidate and other issues. (2)\n(iii) It diverts attention from issues like poverty, development and corruption. (1)", "case"),
    ]
  },
  "political-parties": {
    mcq: [
      M(1, "The three components of a political party are leaders, active members and", "followers", ["judges", "officials", "soldiers"], "Every party has these three components."),
      M(1, "The CPI(M) was founded in", "1964", ["1885", "1951", "1984"], "The Indian National Congress was founded in 1885 and the BSP in 1984."),
      M(1, "NDA, UPA and the Left Front are examples of", "alliances or fronts", ["one-party systems", "national parties", "pressure groups"], "Several parties join together to contest elections and win power."),
      M(1, "The Bharatiya Janata Party was founded in", "1980", ["1951", "1964", "1984"], "It revived the Bharatiya Jana Sangh, formed in 1951."),
      M(1, "The Bharatiya Jana Sangh was formed in 1951 by", "Syama Prasad Mukherjee", ["Kanshi Ram", "Jawaharlal Nehru", "Subhas Chandra Bose"], "The BJP was formed in 1980 after the Janata Party period."),
      M(1, "Recognised political parties are given a unique", "election symbol", ["state bungalow", "television channel", "flag of the state"], "The symbol helps even those who cannot read to identify their party."),
      M(1, "India has which type of party system?", "Multi-party system", ["One-party system", "Two-party system", "No-party system"], "In a multi-party system more than two parties can come to power alone or in alliance."),
      M(1, "Without parties, every candidate in an election would be", "independent", ["a minister", "a judge", "a national leader"], "No one would be responsible for how the country is run."),
      M(2, "Along with a vote share of 6 per cent, a party must win at least how many Lok Sabha seats to be a national party?", "4", ["2", "6", "10"], "A state party needs 6 per cent of votes and at least 2 seats in the assembly."),
      M(2, "Since 1996, nearly every State party has had a chance to", "join a national-level coalition government", ["win all the Lok Sabha seats", "run a one-party state", "be banned"], "State parties have become important in national politics."),
      M(2, "Dynastic succession in parties means", "posts go to leaders' families", ["leaders are chosen by the members", "parties merge with rival parties", "leaders retire at the age of sixty"], "It is a challenge to internal democracy."),
      M(2, "The Election Commission has ordered political parties to", "hold internal elections and file returns", ["share tickets equally among all castes", "stop contesting elections for five years", "merge with other national parties"], "These were measures to reform parties."),
      M(2, "A suggested reform for parties is to give", "one-third of the tickets to women candidates", ["no election symbols", "tickets only to the leaders' families", "a single national party"], "It is also suggested to have state funding of elections."),
      M(2, "Parties give people access to", "government machinery and welfare schemes", ["private banks", "foreign embassies", "court judgments only"], "Parties also shape public opinion."),
      M(2, "A multi-party system can lead to", "political instability", ["a dictatorship", "a lack of choice", "one-party rule"], "It allows a variety of interests to be represented but may be unstable."),
      M(2, "Democracies need parties to", "make someone responsible for governing", ["ban elections", "remove the opposition", "divide power equally among all citizens"], "Parties gather different views and run the government responsibly."),
      M(2, "Which of these is NOT a function of a political party?", "Holding the elections", ["Contesting elections", "Shaping public opinion", "Forming governments"], "The Election Commission conducts elections."),
      M(3, "Match: (1) one-party system, (2) two-party system, (3) multi-party system, (4) alliance. With: (P) USA and UK, (Q) India, (R) China, (S) NDA or UPA.", "1-R, 2-P, 3-Q, 4-S", ["1-P, 2-R, 3-Q, 4-S", "1-R, 2-P, 3-S, 4-Q", "1-R, 2-Q, 3-P, 4-S"], "China has one party, USA and UK two parties, India many parties."),
      M(3, "In a State Assembly election the results are: A - 8% votes, 3 seats; B - 5% votes, 4 seats; C - 6% votes, 2 seats; D - 7% votes, 1 seat. Which parties qualify as state parties?", "A and C", ["A and B", "B and D", "C and D"], "A state party needs at least 6 per cent of votes and 2 seats."),
      M(3, "Which reform of the party system was made by amending the Constitution?", "The anti-defection law", ["The affidavit order", "The order for organisational elections", "The order to file income tax returns"], "The affidavit was ordered by the Supreme Court and the others by the Election Commission."),
      AR(2, "Without parties no one would be responsible for governing the country.", "Every candidate would be an independent and could not promise any major policy changes.", 0, "Without parties there is no team to hold accountable."),
      AR(2, "Parties are needed in a representative democracy.", "They gather different views and bring them before the government.", 0, "Without parties, views would remain scattered and no one would be responsible for governing."),
      AR(2, "Political parties suffer from a lack of internal democracy.", "Power is concentrated in a few top leaders and regular organisational elections are not held.", 0, "Members do not get to choose their leaders."),
      AR(3, "Voters often have no meaningful choice between parties.", "Ideological differences among parties have narrowed.", 0, "When parties resemble each other, choice becomes limited."),
      AR(3, "State parties have become important in national politics.", "Since 1996 nearly every State party has been part of a national-level coalition government.", 0, "Coalition government has given them a role at the Centre."),
    ],
    written: [
      W(2, "What is meant by partisanship in the context of political parties?", "A political party is a 'part' of society and supports one section or one set of policies.\nPartisanship means a firm commitment to the party's position, so that it does not see all sides equally."),
      W(2, "How do political parties shape public opinion?", "They raise and highlight issues, and thousands of activists spread the issues.\nParties often launch movements for the resolution of problems faced by people."),
      W(2, "What is the anti-defection law? Why was it introduced?", "A law by which an MLA or MP who changes parties after being elected loses the seat.\nIt was introduced to end the practice of leaders changing parties for personal gain."),
      W(2, "Name the three components of a political party and state the role of one.", "Leaders, active members and followers.\nLeaders decide the party's policies and choose candidates; active members work for the party."),
      W(3, "State the conditions for a party to be recognised as (a) a state party and (b) a national party.", "(a) State party: at least 6 per cent of votes in the State Legislative Assembly election and at least 2 seats.\n(b) National party: at least 6 per cent of votes in Lok Sabha elections or Assembly elections in four States.\nIt must also win at least 4 Lok Sabha seats."),
      W(3, "What is the role of the opposition in a democracy? Give three points.", "Parties that lose elections play the role of opposition to the party or alliance in power.\nThey voice different views and criticise the government for its failures or wrong policies.\nThey mobilise opposition to the government."),
      W(3, "Explain how money and muscle power affect political parties.", "Parties raise funds from rich people and companies and may favour them.\nParties nominate candidates who can raise a lot of money and win elections even if they have criminal backgrounds.\nThis reduces fairness in elections and the chance of ordinary people to win."),
      W(3, "State three steps taken to reform political parties in India.", "The Constitution was amended to prevent MLAs and MPs from changing parties: the anti-defection law.\nThe Supreme Court ordered that every candidate must file an affidavit giving details of property and criminal cases.\nThe Election Commission ordered that parties must hold organisational elections and file income tax returns."),
      W(5, "Why are political parties necessary for a democracy? Explain with five points.", "Without parties every candidate would be independent, so no one could promise any major policy changes.\nElected representatives would be accountable only to their constituency and no one would be responsible for the country as a whole.\nParties gather different views and bring them before the government, a vital function in a representative democracy.\nParties form and run governments and make laws through their members in the legislature.\nParties in opposition criticise the government and give voters a choice; parties also shape public opinion and give access to welfare schemes."),
      W(4, "Case study: In a Lok Sabha election, a party gets 7 per cent of the votes polled in the country and wins 5 seats. In the Assembly elections it gets 6 per cent in only one State and wins 3 seats.\n(i) Under which conditions is a party a national party? (2)\n(ii) Can this party be a national party? Give a reason. (1)\n(iii) Which authority registers and recognises parties? (1)", "(i) At least 6 per cent of votes in Lok Sabha elections or Assembly elections in four States, and at least 4 Lok Sabha seats. (2)\n(ii) Yes, because it has more than 6 per cent of votes and 5 seats, which is more than the minimum of 4. (1)\n(iii) The Election Commission. (1)", "case"),
    ]
  },
  "outcomes-of-democracy": {
    mcq: [
      M(1, "The Right to Information helps democracy by", "making the government transparent", ["raising taxes on citizens", "fixing the prices of goods", "controlling the press and media"], "It lets citizens examine whether decisions were taken through correct procedures."),
      M(1, "The difference in economic growth between dictatorships and democracies is", "negligible", ["huge", "negative", "unknown"], "Dictatorships had a slightly higher rate, but the difference is negligible."),
      M(1, "Democracy is only a", "form of government", ["economic system", "social custom", "religion"], "It creates conditions for achieving goals, which citizens must use."),
      M(1, "Political equality in a democracy means every citizen has", "one vote of equal value", ["votes counted by wealth", "two votes if educated", "a vote only if a property owner"], "This is the base of democratic equality."),
      M(1, "Democracy has turned people from subjects into", "citizens", ["slaves", "soldiers", "traders"], "Citizens are critical and expect more."),
      M(1, "Democracy is preferred because it allows room to", "correct mistakes", ["hide mistakes", "punish critics", "avoid elections"], "It enables citizens to correct errors."),
      M(1, "Democracy promotes the dignity of the individual and", "freedom of citizens", ["control of citizens by the army", "rule by one community", "unequal votes"], "It does this better than other forms of government."),
      M(1, "Democracy ensures the people's right to choose", "their rulers", ["only the judges", "army chiefs", "foreign advisers"], "Democratic government is accountable to those who elect it."),
      M(2, "Besides the form of government, economic development depends on a country's economic priorities, cooperation from other countries and", "the global situation", ["the number of parties", "the size of the army", "the national song"], "Population size is also a factor."),
      M(2, "Decisions in a democracy are generally", "more acceptable and effective", ["quick but unpopular", "taken in secret", "arbitrary"], "They are based on deliberation and negotiation."),
      M(2, "A growing economic inequality in democracies means that", "the ultra-rich hold a large share of income", ["everyone has an equal share of income", "the poor have the largest share of income", "only the rich lose a part of income"], "Those at the bottom have very little."),
      M(2, "Which country is mentioned in the text as a contrast with Belgium in handling diversity?", "Sri Lanka", ["Switzerland", "USA", "India"], "Belgium shared power, while Sri Lanka followed majoritarianism."),
      M(2, "For democracy to accommodate diversity, rule by the majority must not become", "rule by the majority community", ["rule by elected members", "rule by law", "rule of the people"], "The majority and minority must work together."),
      M(2, "Democracy in India has strengthened the claims of", "disadvantaged castes for equal status", ["landlords for special privileges", "traders for a free monopoly", "kings for a ruling role"], "It has made equality a recognised principle."),
      M(2, "The rising complaints of people against democracy show that it has", "created critical citizens", ["failed completely", "ended elections", "made citizens silent and passive"], "Complaints are a testimony to the success of democracy."),
      M(2, "Transparency means citizens have the right and means to", "examine how decisions were taken", ["appoint ministers by themselves", "fix prices of goods", "amend laws alone"], "Open debate and free elections help in this."),
      M(2, "An accountable government is one whose rulers", "are answerable to the people", ["cannot be questioned", "are appointed for life", "are elected only by the elite"], "Citizens have control over the rulers."),
      M(3, "Match: (1) accountability, (2) responsiveness, (3) legitimacy, (4) transparency. With: (P) citizens can examine procedures, (Q) the government is people's own, (R) rulers are answerable to the people, (S) government attends to the needs and demands of the people.", "1-R, 2-S, 3-Q, 4-P", ["1-S, 2-R, 3-Q, 4-P", "1-R, 2-S, 3-P, 4-Q", "1-Q, 2-S, 3-R, 4-P"], "These are the main outcomes of a democratic government."),
      M(3, "In a democracy, the top 10 per cent of people hold 60 per cent of the national income and the bottom 50 per cent hold 10 per cent. This shows", "high economic inequality despite political equality", ["that income is equally shared", "that the poor are powerless in elections", "that growth is negative"], "Every citizen has one vote, but incomes are very unequal."),
      M(3, "Dictatorships had a slightly higher growth rate, yet democracy is preferred because", "the difference is negligible, and gains are many", ["growth does not matter at all for nations", "dictators are always more honest rulers", "democracies have no inequality at all"], "Democracy also promotes dignity, accountability and legitimacy."),
      AR(2, "Democratic governments take more time to decide.", "They are based on deliberation and negotiation.", 0, "Consultation takes time but makes decisions more acceptable."),
      AR(3, "Democracy guarantees economic development.", "Economic development also depends on population, the global situation, cooperation of other countries and priorities.", 3, "Democracy does not guarantee growth, so A is false."),
      AR(2, "Democracies reduce the chance of conflicts becoming violent.", "They develop procedures to conduct competition among groups.", 0, "Fixed procedures channel disagreements peacefully."),
      AR(3, "Democracy has fallen short in reducing poverty.", "The poor form a large share of voters, yet governments are not always keen to address poverty.", 1, "Both are true; the second is a related observation rather than the full explanation."),
      AR(2, "Democracy promotes the dignity of women.", "Long struggles have made the equal respect and dignity of women a principle with legal and moral force.", 0, "The recognition of equality came through struggles in democratic societies."),
    ],
    written: [
      W(2, "What is transparency in a democratic government?", "Citizens have the right and means to examine whether a decision was taken through the correct procedures.\nTools include free and fair elections, open public debate and the Right to Information."),
      W(2, "Why is economic inequality a problem for democracy?", "A small number of ultra-rich enjoy a disproportionate share of wealth while the poor have very little.\nIt goes against the principle of equality, even though every citizen has one vote."),
      W(2, "What is meant by an accountable government?", "A government in which people have the right to choose their rulers and have control over them.\nThe rulers answer to the people for their decisions."),
      W(2, "How has democracy helped disadvantaged castes in India?", "It has strengthened their claims for equal status and opportunity.\nCompetition for votes has made leaders listen to them."),
      W(3, "How does democracy improve the quality of decision-making? Give three points.", "Decisions are made after consultation and discussion.\nThey are more acceptable to the people and effective.\nA wide range of views is considered and mistakes can be corrected."),
      W(3, "Why is democracy still preferred even though it does not always lead to higher economic growth? Give three reasons.", "The difference in growth between dictatorships and democracies is negligible.\nGrowth depends on many other factors such as population, global situation and priorities.\nDemocracy has other benefits such as dignity, equality, accountability and a way to correct mistakes."),
      W(3, "How does Belgium show that democracy can accommodate social diversity?", "Belgium recognised the differences of Dutch and French speakers and shared power among them.\nIt used equal ministers, regional governments and community governments.\nThis reduced tension and avoided violence, unlike the majoritarian policies in Sri Lanka."),
      W(3, "State three factors on which a country's economic development depends besides its form of government.", "The population size of the country.\nThe global situation and cooperation from other countries.\nThe economic priorities adopted by the country."),
      W(5, "Evaluate the performance of democracy on the basis of its outcomes. Which outcomes are strong and which weak?", "Strong: democracy gives an accountable government where people choose and control rulers; decisions take time but are more acceptable.\nIt is a legitimate, people's own government and is transparent through elections, debate and the Right to Information.\nIt is best at accommodating social diversity by working with minorities and not letting the majority community rule.\nIt promotes dignity and freedom, as in the equal respect for women and the claims of disadvantaged castes.\nWeak: it does not guarantee growth, though the difference from dictatorship is negligible; it has fallen most short in reducing economic inequality and poverty.\nPeople's complaints are a sign of its success, as citizens now expect more."),
      W(4, "Case study: A newspaper letter says: 'In our democracy, the poorest 20 per cent of households own a tiny part of the national wealth while a few families own a very large part. Yet each of them has the same one vote.'\n(i) What is the type of equality that all citizens enjoy? (1)\n(ii) What kind of inequality does the letter point to? (1)\n(iii) Why is this considered a weakness of democracy? (2)", "(i) Political equality (one vote, one value). (1)\n(ii) Economic inequality. (1)\n(iii) Any two: democracy is based on equality, but wealth and income are very unequal; governments are not always keen to reduce poverty even though the poor are a large share of voters; this is the area where democracy has fallen most short of expectations. (2)", "case"),
    ]
  },
  });
})();
